<script setup>
import {ref,onMounted} from 'vue';
import {api} from './native.js';
import Icon from './Icon.vue';
const props=defineProps({disabled:Boolean}),emit=defineEmits(['pick']),items=ref([]),error=ref(''),busy=ref(false),loading=ref(true);
async function load(){try{items.value=(await api('/api/chat/stickers')).items;error.value='';}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function remove(item){busy.value=true;try{await api('/api/chat/stickers','DELETE',{id:item.id});await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(load);
</script>
<template><section class="saved-chat-panel" aria-label="收藏表情包"><small>{{loading?'正在读取…':`已收藏 ${items.length} / 100`}}{{disabled?' · 本条图片已满':''}}</small><p v-if="error" role="alert" class="danger-text">{{error}}<button type="button" @click="load">重试</button></p><div class="saved-chat-stickers"><article v-for="item in items" :key="item.id"><button type="button" :disabled="busy||disabled" :aria-label="'使用表情包：'+(item.label||'图片')" @click="emit('pick',item)"><img :src="'/community'+item.url" :alt="item.label" loading="lazy" decoding="async"></button><button type="button" class="sticker-remove" aria-label="移除收藏" :disabled="busy" @click="remove(item)"><Icon name="trash"/></button></article></div><p v-if="!loading&&!items.length&&!error" class="sticker-empty">在聊天图片中选择“收藏为表情”，就会显示在这里。</p></section></template>
<style>.saved-chat-panel{min-height:0;overflow:auto;max-height:172px;padding:4px 12px 12px}.saved-chat-panel>small{font-size:.75rem;color:var(--muted)}.saved-chat-stickers{display:grid;grid-template-columns:repeat(auto-fill,64px);justify-content:start;gap:10px;margin:8px 0 0}.saved-chat-stickers article{position:relative;min-width:0;height:64px}.saved-chat-stickers article>button:first-child{border-radius:10px;border:1px solid var(--line);height:64px;width:64px;padding:5px;background:var(--soft);overflow:hidden}.saved-chat-stickers img{display:block;height:100%;width:100%;object-fit:contain}.saved-chat-stickers .sticker-remove{position:absolute;bottom:-4px;right:-4px;background:var(--surface);border:1px solid var(--line);border-radius:8px;width:28px;height:28px;min-width:28px;min-height:28px;padding:5px}.sticker-remove .icon{width:16px;height:16px}.sticker-empty{font-size:.8rem;line-height:1.7;color:var(--muted);padding:12px 0}.emoji-panel .chips{gap:4px;flex-wrap:nowrap}.emoji-panel .chips>button{min-height:40px;padding:6px 10px;white-space:nowrap;font-size:.8rem}.emoji-panel .chips>.icon-button{margin-left:auto;width:36px;min-width:36px;height:40px}</style>
